tests.pseudocode:
out := Scan(ctx, ScanInput{Root: root, Changed: files, Added: added, Today: now})
// compare with known-good output from the pre-change code path
assert out matches expected findings

out := Scan(ctx, ScanInput{...})
neutral_checks := {CheckDiscardedError, CheckLaterTask, CheckGitInitBranch, CheckFutureDate, CheckErrataCitation}
for f in out:
  if f.Check in neutral_checks:
    assert f.Backend == ""
    assert f.Profile == ""

files := glob("internal/conform/*.go", exclude _test.go)
for f in files:
  if f != table_file:
    assert no regexp.MustCompile matching formatter output patterns

// Run TestNoLanguageLiterals and verify it covers internal/conform
// The test itself walks the directory and checks each line
assert test walks "internal/conform" directory
assert test checks denylist strings

denylist := [".go\"", "\"go.mod\"", "gofmt", "\"go test\"", "\"go vet\"", "_test.go\"", ...]
for f in glob("internal/conform/*.go", exclude _test.go):
  for line in readLines(f):
    if isImportPath(line): continue
    for d in denylist:
      assert d not in line

// Verify that Revert's signature is backward-compatible
// Existing callers: conform.Revert(ctx, git, root, head, changed, checkFn)
assert Revert signature accepts the same positional args as before
